document.getElementById('quiz-form').addEventListener('submit', function(event) {
    event.preventDefault();

    const answers = {
        q1: ['cpp', 'java', 'rust'],
        q2: ['html', 'css', 'javascript'],
        q3: ['haskell', 'lisp', 'elixir']
    };

    let score = 0;
    const totalQuestions = Object.keys(answers).length;

    for (const [question, correctOptions] of Object.entries(answers)) {
        const selectedOptions = Array.from(document.querySelectorAll(`input[name="${question}"]:checked`))
                                     .map(cb => cb.value);

        // Simple scoring logic: all correct must be selected, no incorrect should be selected
        const isCorrect = selectedOptions.length === correctOptions.length &&
                          selectedOptions.every(val => correctOptions.includes(val));

        if (isCorrect) {
            score++;
        }
    }

    const resultsDiv = document.getElementById('results');
    resultsDiv.textContent = `You got ${score} out of ${totalQuestions} questions correct!`;
    resultsDiv.className = 'success';
});

